package com.zorykai.fishing;
import com.mojang.brigadier.builder.LiteralArgumentBuilder;
import com.mojang.brigadier.arguments.*;
import net.minecraft.server.command.ServerCommandSource;
import net.minecraft.command.argument.EntityArgumentType;
import static net.minecraft.server.command.CommandManager.*;
import java.util.*;
/** Mutations are audited; money attestation is deliberately explicit and never retried automatically. */
final class AdminCommands {
 static void register(FishingMod m,LiteralArgumentBuilder<ServerCommandSource> root){
  var time=literal("tempo");for(String action:List.of("ver","add","set","reset")){var target=argument("jogador",EntityArgumentType.player());if(action.equals("ver")||action.equals("reset"))target.executes(c->m.guarded(c.getSource(),()->{var p=EntityArgumentType.getPlayer(c,"jogador");if(action.equals("reset"))m.data.update(p.getUuid(),d->{d.cycleStart=0;return null;});var d=m.sessions.renew(p);FishingMod.reply(c.getSource(),"Tempo de "+p.getGameProfile().getName()+": "+m.sessions.balance(d)+" segundos");m.audit(p.getUuid(),"ADMIN_TIME_"+action,Map.of("by",c.getSource().getName()));return 1;}));else target.then(argument("minutos",IntegerArgumentType.integer(0,100000)).executes(c->m.guarded(c.getSource(),()->{var p=EntityArgumentType.getPlayer(c,"jogador");int minutes=IntegerArgumentType.getInteger(c,"minutos");m.sessions.renew(p);m.data.update(p.getUuid(),d->{if(action.equals("set")){d.remainingSeconds=0;d.credits.clear();}m.sessions.addTime(d,minutes*60L,24);return null;});m.audit(p.getUuid(),"ADMIN_TIME_"+action,Map.of("minutes",minutes,"by",c.getSource().getName()));return 1;})));time.then(literal(action).then(target));}root.then(time);
  root.then(literal("xp").then(literal("add").then(argument("jogador",EntityArgumentType.player()).then(argument("quantidade",IntegerArgumentType.integer(1,1000000000)).executes(c->m.guarded(c.getSource(),()->{var p=EntityArgumentType.getPlayer(c,"jogador");int amount=IntegerArgumentType.getInteger(c,"quantidade");m.data.update(p.getUuid(),d->{d.xp=Math.addExact(d.xp,amount);return null;});m.audit(p.getUuid(),"ADMIN_XP",Map.of("amount",amount,"by",c.getSource().getName()));return 1;}))))));
  for(String type:List.of("vara","missao")){root.then(literal(type).then(literal(type.equals("vara")?"dar":"completar").then(argument("jogador",EntityArgumentType.player()).then(argument("id",StringArgumentType.word()).executes(c->m.guarded(c.getSource(),()->{var p=EntityArgumentType.getPlayer(c,"jogador");String id=StringArgumentType.getString(c,"id");if(type.equals("vara")){m.rules.definition("rods",id);m.data.update(p.getUuid(),d->{d.rods.putIfAbsent(id,new com.zorykai.fishing.core.PlayerData.Rod());return null;});}else{var q=m.progress.quests().stream().filter(x->GameConfig.str(x,"id","").equals(id)).findFirst().orElseThrow();m.data.update(p.getUuid(),d->{m.progress.quest(d,q).progress=GameConfig.num(q,"target",1);return null;});}m.audit(p.getUuid(),"ADMIN_"+type,Map.of("id",id,"by",c.getSource().getName()));return 1;}))))));}
  root.then(literal("sessao").then(literal("encerrar").then(argument("jogador",EntityArgumentType.player()).executes(c->m.guarded(c.getSource(),()->{var p=EntityArgumentType.getPlayer(c,"jogador");m.sessions.exit(p);m.audit(p.getUuid(),"ADMIN_SESSION_END",Map.of("by",c.getSource().getName()));return 1;})))));
  var ledger=literal("transacao");ledger.then(literal("ver").then(argument("jogador",EntityArgumentType.player()).executes(c->m.guarded(c.getSource(),()->{var tx=m.finance.pending(EntityArgumentType.getPlayer(c,"jogador").getUuid());FishingMod.reply(c.getSource(),tx==null?"Sem pendência":tx.toString());return 1;}))));
  for(String action:List.of("confirmar-aplicada","confirmar-nao-aplicada"))ledger.then(literal(action).then(argument("jogador",EntityArgumentType.player()).then(argument("id",StringArgumentType.word()).executes(c->m.guarded(c.getSource(),()->{var p=EntityArgumentType.getPlayer(c,"jogador");m.finance.resolve(p.getUuid(),StringArgumentType.getString(c,"id"),action.equals("confirmar-aplicada"));m.audit(p.getUuid(),"ADMIN_FINANCE_RESOLVE",Map.of("by",c.getSource().getName(),"action",action));return 1;})))));root.then(ledger);
 }
}
